export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export interface CatalogInput { catalogRecordId: string; catalogRevision:number; bundle: { taxonomy_version: string; catalog: { catalog_id: string; source_sha256: string }; items: Array<{ catalog_item: { source_item_id: string; class_id: string; [key: string]: JsonValue } }> } }
export interface MatcherInput { requestBundle: { taxonomy_version: string; request_document: { request_id: string; lines: Array<{ line_id: string; class_id: string; [key: string]: JsonValue }> } }; catalogs: CatalogInput[]; policy: { policy_registry_version: string; catalog_record_ids: string[]; catalog_priority: string[]; brands: { include: string[]; exclude: string[]; preferred: string[]; unknown: 'allow'|'exclude' }; max_match_level: 'exact'|'equivalent'|'alternative'; catalog_needs_review: 'exclude'|'manual_only'; [key:string]: JsonValue }; registry: { policy_version: string; [key:string]: JsonValue }; engineVersion: 'pilot-1.0.0' }
export interface MatchResult { schema_version:'1.0.0'; kind:'match_result'; engine_version:'pilot-1.0.0'; policy_registry_version:string; taxonomy_version:string; request_id:string; input_fingerprint:string; policy:MatcherInput['policy']; catalog_refs:Array<{catalog_record_id:string;catalog_id:string;source_sha256:string;catalog_revision?:number}>; lines:JsonValue[]; summary:Record<string,number> }
export class MatchingInputError extends Error { readonly code:string; readonly path:string }
export function runPilotMatcher(input: MatcherInput): Promise<MatchResult>;
